 AS order_item_label FROM ( SELECT *, COUNT(SaleOrderItemCode) OVER (PARTITION BY Reference_Code) AS item_count FROM maplemonk.saadaa_returns_consolidated ) t; CREATE OR REPLACE TABLE saadaa-wh.maplemonk.saadaa_returns_count_data as WITH orders as ( SELECT LAST_DAY(date(order_date), MONTH) as order_month, DATE_TRUNC(order_Date, MONTH) as month_first_date, date(order_date) as order_date, marketplace, count(distinct reference_code) as orders_for_the_month, COUNT(DISTINCT CASE WHEN (return_flag = 1 and return_request_type = \'return\') THEN reference_code END) AS total_returned_orders_for_orders_of_month, sum(case when (return_flag=1 and return_request_type = \'return\') then 1 else 0 end) as total_returned_items_for_orders_of_month, sum(case when (return_flag=1 and return_request_type = \'return\') then TOTAL_RETURNED_QUANTITY else 0 end) as total_returned_quantity_for_orders_of_month, COUNT(DISTINCT CASE WHEN (return_flag = 1 and return_request_type = \'exchange\') THEN reference_code END) AS total_exchange_orders_for_orders_of_month, sum(case when (return_flag=1 and return_request_type = \'exchange\') then 1 else 0 end) as total_exchange_items_for_orders_of_month, sum(case when (return_flag=1 and return_request_type = \'exchange\') then TOTAL_RETURNED_QUANTITY else 0 end) as total_exchange_quantity_for_orders_of_month, count(*) as total_order_items_for_the_month, sum(order_quantity) as total_order_quantity_for_the_month, sum(total_sales) as total_sales FROM saadaa-wh.maplemonk.saadaa_returns_consolidated GROUP BY LAST_DAY(date(order_date), MONTH),DATE_TRUNC(order_Date, MONTH), date(order_date),marketplace ), returns as ( SELECT LAST_DAY(DATE(coalesce(return_refunded_at,original_return_request_date)), MONTH) as return_month, date(coalesce(return_refunded_at,original_return_request_date)) as return_date, marketplace, COUNT(*) as total_returned_items_received_in_month, count(distinct reference_code) as returned_orders_received_in_month, sum(ifnull(TOTAL_RETURNED_QUANTITY,0)) as returned_quantity_received_in_month, sum(ifnull(total_refund_amount,0)) as total_returned_sales FROM saadaa-wh.maplemonk.saadaa_returns_consolidated WHERE return_flag = 1 and return_request_type = \'return\' GROUP BY LAST_DAY(DATE(coalesce(return_refunded_at,original_return_request_date)), MONTH),date(coalesce(return_refunded_at,original_return_request_date)),marketplace ), exchanges as ( SELECT LAST_DAY(DATE(original_return_request_date), MONTH) as return_month, date(original_return_request_date) as return_date, marketplace, COUNT(*) as total_exchange_items_received_in_month, count(distinct reference_code) as exchange_orders_received_in_month, sum(TOTAL_RETURNED_QUANTITY) as exchange_quantity_received_in_month, FROM saadaa-wh.maplemonk.saadaa_returns_consolidated WHERE return_flag = 1 and return_request_type = \'exchange\' GROUP BY LAST_DAY(DATE(original_return_request_date), MONTH),date(original_return_request_date),marketplace ), rtos as ( SELECT LAST_DAY(DATE(original_return_request_date), MONTH) as return_month, date(original_return_request_date) as return_date, marketplace, COUNT(*) as total_rto_items_received_in_month, count(distinct reference_code) as rto_orders_received_in_month, sum(TOTAL_RETURNED_QUANTITY) as rto_quantity_received_in_month, FROM saadaa-wh.maplemonk.saadaa_returns_consolidated WHERE return_flag = 1 and return_request_type = \'RTO\' GROUP BY LAST_DAY(DATE(original_return_request_date), MONTH),date(original_return_request_date),marketplace ) SELECT o.month_first_date, o.marketplace, o.order_month, o.order_date, o.orders_for_the_month, o.total_order_items_for_the_month, o.total_order_quantity_for_the_month, o.total_returned_orders_for_orders_of_month, o.total_returned_items_for_orders_of_month, o.total_returned_quantity_for_orders_of_month, o.total_exchange_orders_for_orders_of_month, o.total_exchange_items_for_orders_of_month, o.total_exchange_quantity_for_orders_of_month, o.total_sales, r.total_returned_sales, r.return_date, r.total_returned_items_received_in_month, r.returned_orders_received_in_month, r.returned_quantity_received_in_month, e.total_exchange_items_received_in_month, e.exchange_orders_received_in_month, e.exchange_quantity_received_in_month, rt.total_rto_items_received_in_month, rt.rto_orders_received_in_month, rt.rto_quantity_received_in_month from orders o LEFT JOIN returns r ON r.return_date = o.order_date and r.marketplace = o.marketplace LEFT JOIN exchanges e ON e.return_date = o.order_date and e.marketplace = o.marketplace LEFT JOIN rtos rt ON rt.return_date = o.order_date and rt.marketplace = o.marketplace order by order_date desc; create or replace table maplemonk.saadaa_stn_returns_consolidated as select e.reference_code ,e.Marketplace_LineItem_ID AS SALEORDERITEMCODE ,e.ORDER_ID ,Upper(e.order_status) as order_status ,cast(e.ORDER_DATE as datetime) AS Order_Date ,cast(DELIVERED_DATE as datetime) as Delivered_Date ,UPPER(e.marketplace) AS marketplace ,UPPER(e.marketplace) AS MARKETING_CHANNEL ,UPPER(e.marketplace) AS SOURCE ,UPPER(e.PRODUCTNAME) AS PRODUCT_NAME ,e.SKU ,UPPER(e.mapped_category) AS product_category ,UPPER(e.mapped_sub_category) AS product_sub_category ,e.suborder_quantity as order_quantity ,UPPER(e.CITY) AS City ,UPPER(e.STATE) AS State ,e.pincode ,UPPER(e.COURIER) AS Shipping_Courier ,e.awb ,e.customer_name AS NAME ,e.email AS EMAIL ,cast(null as string) as return_request_number ,cast(r.return_date as datetime) as final_return_request_date ,cast(r.return_date as datetime) as original_return_request_date ,cast(null as int64) as no_of_return_requests_initiated ,cast(null as array<string>) as list_of_pickup_couriers_assigned ,cast(null as datetime) as return_approved_date ,cast(null as datetime) as return_refunded_at ,cast(null as datetime) as return_inspected_date ,cast(r.return_date as datetime) as return_date ,case when coalesce((case when Return_Initiated_Date is not null then 1 end),e.is_refund) = 1 then \'Approved\' else null end as return_approval_status ,case when lower(r.return_type) like \'%courier%\' or lower(r.seller_return_reason) like \'%rto%\' or lower(r.seller_return_reason) like \'%cancel%\' then \'RTO\' when lower(r.channel_return_reason) like \'%change%\' then \'exchange\' when coalesce((case when return_date is not null then 1 end),e.is_refund) = 1 then \'return\' else null end as return_request_type ,case when lower(r.return_type) like \'%courier%\' or lower(r.seller_return_reason) like \'%rto%\' or lower(r.seller_return_reason) like \'%cancel%\' then \'RTO\' when lower(r.return_type) like \'%customer%\' then \'return\' when lower(r.channel_return_reason) like \'%change%\' then \'exchange\' when lower(r.channel_return_reason) like \'%lost%\' then \'lost\' else cast(null as string) end as return_type ,coalesce((case when return_date is not null then 1 end),e.is_refund) as return_flag ,r.RETURNED_QUANTITY as TOTAL_RETURNED_QUANTITY ,coalesce(r.channel_return_reason,r.seller_return_reason) as return_reason ,e.Payment_mode ,e.selling_price ,r.PRODUCT_NAME as returned_product_name ,REGEXP_EXTRACT(r.sku, r\'_([^_]+)$\') as returned_product_variant ,r.SKU as returned_sku ,case when e.is_refund = 1 then e.selling_price else 0 end as returned_product_price ,case when e.is_refund = 1 then e.tax else 0 end as TOTAL_RETURN_TAX ,null as TOTAL_RETURN_AMOUNT_EXCL_TAX ,r.saleorderitemcode as returned_item_saleorderitemcode ,case when lower(r.channel_return_reason) like \'%change%\'then r.PRODUCT_NAME end as exchange_product_name ,case when lower(r.channel_return_reason) like \'%change%\'then REGEXP_EXTRACT(r.sku, r\'_([^_]+)$\') end as exchange_product_variant ,case when lower(r.channel_return_reason) like \'%change%\'then r.sku end as exchange_sku ,case when lower(r.channel_return_reason) like \'%change%\'then e.selling_price end as exchange_product_total_price ,cast(null as string) as exchange_status ,e.order_status as oms_order_status ,CASE WHEN e.pincode LIKE \'1%\' OR e.pincode LIKE \'2%\' THEN \'North Region\' WHEN e.pincode LIKE \'3%\' OR e.pincode LIKE \'4%\' THEN \'West Region\' WHEN e.pincode LIKE \'5%\' OR e.pincode LIKE \'6%\' THEN \'South Region\' WHEN e.pincode LIKE \'7%\' OR e.pincode LIKE \'8%\' THEN \'East Region\' ELSE NULL END AS region ,DATE_DIFF(date(return_date), date(case when (cast(r.return_date as datetime) > cast(r.return_date as datetime)) then cast(r.return_date as datetime) else cast(Delivered_Date as datetime) end), DAY) AS days_from_delivery ,case when (cast(r.return_date as datetime) > cast(r.return_date as datetime)) then cast(r.return_date as datetime) else cast(Delivered_Date as datetime) end as final_delivery_date ,null as estimated_pickup_date ,r.Total_return_amount as total_refund_amount ,e.Gender ,e.CategoryType ,e.garment_length ,e.Color_Family ,e.Product_Type ,e.Product_Variant ,e.FitType ,e.Sleeve_Type ,e.Neck_Collar_Type from maplemonk.saadaa_easyecom_fact_items e left join (select reference_code, saleorderitemcode, max(Return_Initiated_Date) as Return_Initiated_Date, max(return_date) as return_date, max(return_type) as return_type, max(seller_return_reason) as seller_return_reason, max(channel_return_reason) as channel_return_reason, count(serial_number) as RETURNED_QUANTITY, max(product_name) as PRODUCT_NAME, max(sku) as sku, sum(Total_return_amount) as Total_return_amount from maplemonk.easyecom_saadaa_all_returns where reference_code like \'STN%\' group by 1,2 qualify row_number() over (partition by reference_code,saleorderitemcode order by 1 desc)=1 ) r on e.reference_code = r.reference_code and e.marketplace_lineitem_id = r.saleorderitemcode where e.reference_code like \'%STN%\';",
                    "transaction": true
                }
            ) }}
